pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(uint256 newVal) public {
        vm.assume(newVal != c.MinSum());
        c.Initialized();
        try c.SetMinSum(newVal) { } catch { }
        assertTrue(c.MinSum() == 1 ether);
    }
}
